  `User_Role` varchar(50) DEFAULT NULL,
  `Station_ID` int(11) DEFAULT NULL,
  `IP_Address` varchar(45) DEFAULT NULL,
  `User_Agent` text DEFAULT NULL,
  `Request_URI` varchar(500) DEFAULT NULL,
  `Request_Method` varchar(10) DEFAULT NULL,
  `Request_Data` text DEFAULT NULL,
  `Assigned_To` int(11) DEFAULT NULL,
  `Resolution_Notes` text DEFAULT NULL,
  `Resolved_At` datetime DEFAULT NULL,
  `Resolved_By` int(11) DEFAULT NULL,
  `Created_At` timestamp NOT NULL DEFAULT current_timestamp(),
  `Updated_At` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`Error_ID`),
  KEY `idx_error_type` (`Error_Type`),
  KEY `idx_severity` (`Severity`),
  KEY `idx_module` (`Module`),
  KEY `idx_date_time` (`Date_Time`),
  KEY `idx_status` (`Status`),
  KEY `idx_user_id` (`User_ID`),
  KEY `idx_station_id` (`Station_ID`),
  KEY `idx_assigned_to` (`Assigned_To`),
  KEY `Resolved_By` (`Resolved_By`),
  CONSTRAINT `error_events_ibfk_1` FOREIGN KEY (`User_ID`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `error_events_ibfk_2` FOREIGN KEY (`Station_ID`) REFERENCES `stations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `error_events_ibfk_3` FOREIGN KEY (`Assigned_To`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `error_events_ibfk_4` FOREIGN KEY (`Resolved_By`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



