-- Table: `fuel_reconciliation`
DROP TABLE IF EXISTS `fuel_reconciliation`;
CREATE TABLE `fuel_reconciliation` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `station_id` int(11) NOT NULL,
  `reconciliation_date` date NOT NULL,
  `opening_stock` decimal(10,2) DEFAULT 0.00,
  `deliveries` decimal(10,2) DEFAULT 0.00,
  `sales` decimal(10,2) DEFAULT 0.00,
  `adjustments` decimal(10,2) DEFAULT 0.00,
  `closing_stock` decimal(10,2) DEFAULT 0.00,
  `fuel_type_id` int(11) DEFAULT NULL,
  `fuel_type` varchar(50) DEFAULT NULL,
  `pump_id` int(11) DEFAULT NULL,
  `previous_reading` decimal(10,2) NOT NULL DEFAULT 0.00,
  `present_reading` decimal(10,2) NOT NULL DEFAULT 0.00,
  `calibration` decimal(10,2) DEFAULT 0.00,
  `price_per_liter` decimal(10,2) NOT NULL DEFAULT 0.00,
  `sales_liters` decimal(10,2) GENERATED ALWAYS AS (case when `present_reading` - `previous_reading` - `calibration` > 0 then `present_reading` - `previous_reading` - `calibration` else 0 end) STORED,
  `sales_amount` decimal(12,2) GENERATED ALWAYS AS (case when `present_reading` - `previous_reading` - `calibration` > 0 then (`present_reading` - `previous_reading` - `calibration`) * `price_per_liter` else 0 end) STORED,
  `physical_stock` decimal(10,2) DEFAULT NULL,
  `variance_liters` decimal(10,2) GENERATED ALWAYS AS (coalesce(`sales_liters`,0) - coalesce(`physical_stock`,0)) STORED,
  `variance_percent` decimal(5,2) GENERATED ALWAYS AS (case when `sales_liters` > 0 then (`sales_liters` - coalesce(`physical_stock`,0)) / `sales_liters` * 100 else 0 end) STORED,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `manager_notes` text DEFAULT NULL,
  `status` enum('Pending','Verified','Approved','Rejected','Finalized') NOT NULL DEFAULT 'Pending',
  `verified_by` int(11) DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `variance` decimal(10,2) DEFAULT NULL,
  `finalized_by` int(11) DEFAULT NULL,
  `finalized_at` timestamp NULL DEFAULT NULL,
  `admin_notes` longtext DEFAULT NULL,
  `is_locked` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `fk_fuel_rec_station` (`station_id`),
  KEY `fk_fuel_rec_fuel_type` (`fuel_type_id`),
  KEY `fk_fuel_rec_pump` (`pump_id`),
  KEY `fk_fuel_rec_verifier` (`verified_by`),
  KEY `idx_fuel_recon_station_date` (`station_id`,`reconciliation_date`),
  KEY `idx_fuel_recon_fuel_type` (`fuel_type`),
  KEY `idx_recon_status` (`status`),
  CONSTRAINT `fk_fuel_recon_ftype` FOREIGN KEY (`fuel_type_id`) REFERENCES `fuel_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_fuel_recon_pump` FOREIGN KEY (`pump_id`) REFERENCES `fuel_pumps` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_fuel_reconciliation_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE NO ACTION,
  CONSTRAINT `fk_fuel_reconciliation_verified_by_9bc6` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

