  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` varchar(20) DEFAULT NULL COMMENT 'Employee ID with role prefix (ADM-001, MGR-001, STF-001)',
  `first_name` varchar(100) NOT NULL DEFAULT '',
