  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  UNIQUE KEY `uk_email` (`email`),
  UNIQUE KEY `uk_employee_id` (`employee_id`),
  KEY `fk_user_station` (`station_id`),
  KEY `idx_id_u` (`id`),
  KEY `idx_assigned_shift` (`assigned_shift`),
  CONSTRAINT `fk_users_station_id` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`) ON DELETE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='User accounts with role-based access control and shift assignment for staff';



