  `original_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`original_items`)),
  `adjusted_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`adjusted_items`)),
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_transaction_action` (`transaction_id`,`action`),
  KEY `idx_manager_station` (`manager_id`,`station_id`),
  KEY `idx_staff_station` (`staff_id`,`station_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `station_id` (`station_id`),
  KEY `fk_val_log_pending` (`pending_transaction_id`),
  CONSTRAINT `fk2_validation_actions_log_transaction_id` FOREIGN KEY (`transaction_id`) REFERENCES `fuel_transactions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_val_log_pending` FOREIGN KEY (`pending_transaction_id`) REFERENCES `pending_merchandise_transactions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `validation_actions_log_ibfk_1` FOREIGN KEY (`pending_transaction_id`) REFERENCES `pending_merchandise_transactions` (`id`),
  CONSTRAINT `validation_actions_log_ibfk_2` FOREIGN KEY (`manager_id`) REFERENCES `users` (`id`),
  CONSTRAINT `validation_actions_log_ibfk_3` FOREIGN KEY (`staff_id`) REFERENCES `users` (`id`),
  CONSTRAINT `validation_actions_log_ibfk_4` FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

